window.kbPageData["views/entry/k-125bcf652021e1a9"] = {"key":"entry/k-125bcf652021e1a9","state":{"route":"entry/k-125bcf652021e1a9"},"node":{"id":"k-125bcf652021e1a9","mode":"k","title":"物业安全保障义务与补充责任","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["第三人致损时未尽安全保障义务的管理者承担相应补充责任"],"qs":["江苏 2024 B类 行测#13"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewDoubt":"法条和类似纠纷已核实。仍需核对禁停地点是否属于物业应维护的监控覆盖范围，以及仅影响事后追偿时认定补充责任所需的因果事实。","reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"原题引文：物业公司因监控设施故障无法告知相关情况","review":{"definition":"原题引文：物业公司因监控设施故障无法告知相关情况","explanation":"本题选C，按物业未尽监控管理义务处理。类似停车场纠纷曾把监控缺失导致无法查明侵权人纳入物业过错分析，但该案业主停在约定车位，最终双方和解。万某停在禁停地点，仍需判断物业对该区域的监控维护义务、设备正常时能否帮助查明肇事者，以及违停对损害发生或扩大的影响。题干没有交代足以确定具体责任范围的事实。","references":[{"source":"web-bc3f8ab1e5a22ac1","location":"第九百四十二条、第一千一百七十三条、第一千一百九十八条","quote":"承担相应的补充责任"},{"source":"web-bccbefcdf8ceec2d","location":"案例说明及法官心语","quote":"双方当事人达成和解"}],"evidence":"物业公司因监控设施故障无法告知相关情况","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 B类 行测#13":{"paper":"江苏 2024 B类 行测","n":13,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",5],"card":"ee2a90fcbcdd8389d4a598ca","links":[{"id":"k-125bcf652021e1a9","role":"直接考查","why":"解析将物业未尽监控设施管理义务认定为承担相应补充责任的依据。"}]}},"terms":{},"references":{"web-bc3f8ab1e5a22ac1":{"name":"《中华人民共和国民法典》","url":"https://nmca.miit.gov.cn/zwgk/zcwj/flfg/art/2021/art_fa4b2d35db784827b280bc785e8df7d5.html"},"web-bccbefcdf8ceec2d":{"name":"张湾区人民法院《车辆停放车库被剐蹭，监控无法调取！找不到肇事者！物业该不该赔偿？》","url":"https://www.thepaper.cn/newsDetail_forward_23336336"}},"topics":[],"units":{"k-125bcf652021e1a9":[["江苏 2024 B类 行测#13"]]}};
